MATCH (p:Person)-[:VISITS]->(pl1:Place), (p)-[:VISITS]->(pl2:Place)
WHERE p.healthstatus = "Sick"
  AND EXISTS {
    MATCH (p)-[v1:VISITS]->(pl1)
    WHERE v1.endtime < p.confirmedtime
  }
  AND EXISTS {
    MATCH (p)-[v2:VISITS]->(pl2)
    WHERE v2.starttime > p.confirmedtime
  }
RETURN DISTINCT p.name, p.confirmedtime
